session_start();header('Content-Type: application/json; charset=UTF-8');require_once __DIR__.'/../config/koneksi.php';$d=json_decode(file_get_contents('php://input'),true)?:[];$email=strtolower(trim($d['email']??''));$nama=trim($d['nama']??'');$password=(string)($d['password']??'');$angkatan=trim($d['angkatan']??'');$tahun=trim($d['tahun_lulus']??'');$foto=trim($d['foto']??'');$fakultas=trim($d['fakultas']??'');$univ=trim($d['universitas']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$nama===''||strlen($password)<8||$angkatan===''||$tahun===''||$fakultas===''||$univ===''){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Semua kolom wajib diisi; password minimal 8 karakter']);exit;}
try{$jurusanId=null;$q=$conn->prepare('SELECT id FROM jurusan WHERE nama=? LIMIT 1');$q->bind_param('s',$fakultas);$q->execute();$jurusanId=$q->get_result()->fetch_column()?:null;$q=$conn->prepare('SELECT id FROM universitas WHERE nama=? LIMIT 1');$q->bind_param('s',$univ);$q->execute();$universitasId=$q->get_result()->fetch_column();if(!$universitasId){$q=$conn->prepare('INSERT INTO universitas(nama) VALUES(?)');$q->bind_param('s',$univ);$q->execute();$universitasId=$q->insert_id;}$hash=password_hash($password,PASSWORD_DEFAULT);$q=$conn->prepare("INSERT INTO users(nama,email,password,angkatan,tahun_lulus,foto,jurusan_id,universitas_id,role) VALUES(?,?,?,?,?,?,?,?, 'user')");$q->bind_param('ssssssii',$nama,$email,$hash,$angkatan,$tahun,$foto,$jurusanId,$universitasId);$q->execute();session_regenerate_id(true);$_SESSION['user_id']=$q->insert_id;echo json_encode(['success'=>true,'user'=>['id'=>$_SESSION['user_id'],'nama'=>$nama,'email'=>$email,'angkatan'=>$angkatan,'tahun_lulus'=>$tahun,'foto'=>$foto,'fakultas'=>$fakultas,'universitas'=>$univ]],JSON_UNESCAPED_UNICODE);}catch(mysqli_sql_exception $e){http_response_code($e->getCode()===1062?409:500);echo json_encode(['success'=>false,'message'=>$e->getCode()===1062?'Email sudah terdaftar':'Pendaftaran gagal']);}